// The Chat With Knowledge Base tool needs a search session ID to give the
// chat-tuned service its own conversation history — but creating a fresh
// session on every message would spam the workspace. This looks up whether
// this n8n chat session already has one mapped, the same way
// chat-with-search-session.json does for a direct (non-tool) chat call.
//
// Static data is per-workflow, in-memory-backed storage that n8n persists to
// the database after each execution. It's fine for demos/small deployments,
// but it resets if you clear it manually, and it isn't shared across workers
// in a scaled/queue-mode setup. For production, replace this lookup/store
// pair with a real data store (a Data Table node, a database, Redis, etc.)
// keyed the same way.
const staticData = $getWorkflowStaticData('global');
staticData.searchSessions = staticData.searchSessions || {};

const n8nSessionId = $json.sessionId;
const existingSearchSessionId = staticData.searchSessions[n8nSessionId] || '';

return [
  {
    json: {
      ...$json,
      searchSessionId: existingSearchSessionId,
    },
  },
];

// Runs only the first time a given n8n chat session shows up (the "no
// existing search session" branch): remember the search session Haystack
// Enterprise just created against this n8n chat session, so the next message
// in the same conversation reuses it instead of creating another one.
//
// Reads both the original trigger data and the newly created session ID
// straight off $json — both got combined onto one item by the Merge node
// upstream. Deliberately NOT using $('Look Up Search Session') here: a Code
// node reaching back to another node by name needs an extra round trip to
// the main process under n8n's external Task Runner, and that round trip is
// what was hanging for a full 5 minutes (then erroring with "Task execution
// timed out after 300 seconds") before this was rewritten to only touch
// $json.
const staticData = $getWorkflowStaticData('global');
staticData.searchSessions = staticData.searchSessions || {};

staticData.searchSessions[$json.sessionId] = $json.search_session_id;

return [
  {
    json: {
      ...$json,
      searchSessionId: $json.search_session_id,
    },
  },
];
